// Preventive maintenance, job cards and spares (part 17.05): plans by hours, kilometres or days for a class of equipment or one machine, and the state of each plan on each machine (due from the meter and the date, 17.03/17.04 supply the meter);
// job cards (approval-controlled: the plant supervisor, and the plant manager for a costly external repair) for preventive and breakdown work with the complaint, diagnosis, mechanic, labour, external vendor, downtime and the spares drawn from stores
// (reserved and issued through the stock services of 16.01, so the stock falls); the cost of each job; MTBF and MTTR; warranty claims; and the block on putting a machine with an overdue critical service to work (BR-01).
// Meters and litres are thousandths, hours thousandths, money paise.
export const PLANT_JOB_DOC = 'PLANT_JOB_CARD';
export const JOB_TYPES = { PREVENTIVE: 'Preventive', BREAKDOWN: 'Breakdown' }; export const JOB_STATUS = { OPEN: 'Open', IN_PROGRESS: 'In progress', CLOSED: 'Closed' };
export const INTERVALS = { HOURS: 'Hours of the meter', KM: 'Kilometres', DAYS: 'Days' }; export const PM_STATE = { OK: 'Not yet due', DUE: 'Due', OVERDUE: 'Overdue' };
export const SPARE_STATUS = { REQUESTED: 'Requested', RESERVED: 'Reserved in stores', ISSUED: 'Issued', RETURNED: 'Returned', CANCELLED: 'Cancelled' }; export const WARRANTY = { NONE: 'No claim', CLAIMED: 'Claimed', RECOVERED: 'Recovered', REJECTED: 'Rejected' };
