const hoursBetween = (a, b) => Math.max(0, Math.round(((Date.parse(b) - Date.parse(a)) / 3_600_000) * 1000)); const ist = () => new Date(Date.now() + 5.5 * 3600_000).toISOString().slice(0, 16);
for (const [key, def, description, min, max] of [
  ['plant.maint.external_limit', 50000, 'Rupees: an external repair above this goes to the plant manager after the plant supervisor.', 0, 100000000],
  ['plant.maint.labour_rate', 250, 'Rupees an hour: the internal charge of a mechanic hour on a job card.', 0, 100000],
  ['plant.maint.block_on_overdue', 1, 'BR-01: 1 blocks allocation and logging of a machine that has a critical service overdue; 0 only shows it.', 0, 1],
  ['plant.maint.warn_pct', 10, 'A plan with no warning of its own turns due this percent of its interval before the due meter or date.', 0, 100],
]) if (!parameterRegistry.get(key)) parameterRegistry.define({ key, dataType: 'integer', default: def, scopes: ['system', 'company'], description, min, max });

